'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}),money=v=>typeof v==='number'&&Number.isFinite(v)?nf.format(v)+' ₽':'—';
const when=v=>v?new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'не загружены';
const labels={draft:'Черновик',submitted:'На проверке',returned:'Возвращена',cancelled:'Отменена'};
const eventLabels={created:'Создан черновик',submitted:'Передана на проверку',returned:'Возвращена на доработку',cancelled:'Заявка отменена',note:'Сохранена заметка'};
let data={products:[],batches:[],events:[],priceJobs:{}},filtered=[],page=1,selected=new Set(),editRows=[],quote=null,quoteRequest=null,requestId=null,noteProduct=null,batchId=null,loading=false,editorBusy=false,previewGeneration=0,deepLinkHandled=false;
const pageSize=40;
async function api(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});let d;try{d=await r.json()}catch{throw Error('Сервер недоступен. Обновите страницу.')}if(!r.ok)throw Error(d.error||'Не удалось выполнить запрос');return d}
function notice(text,error=false){$('notice').textContent=text;$('notice').className=error?'error':text?'success':''}
function tab(name){if(!['catalog','queue','journal'].includes(name))name='catalog';for(const key of ['catalog','queue','journal']){$(key+'-panel').hidden=key!==name;$(key+'-tab').setAttribute('aria-selected',String(key===name))}history.replaceState(null,'','#'+name)}
function storeOptions(){const old=$('store').value,market=$('market').value,list=[...new Map(data.products.filter(p=>!market||p.market===market).map(p=>[p.storeId,p.storeName]))];$('store').innerHTML='<option value="">Все магазины</option>'+list.map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('');if(list.some(([id])=>id===old))$('store').value=old}
async function load(){if(loading)return;loading=true;try{data=await api('/api/manage');storeOptions();const keys=new Set(data.products.map(p=>p.key));selected=new Set([...selected].filter(k=>keys.has(k)));render();if(!deepLinkHandled){deepLinkHandled=true;const key=new URLSearchParams(location.search).get('product');const product=data.products.find(p=>p.key===key);if(product)openEditor([product]);}}catch(e){notice(e.message+' Если сервер перезапускался, обновите страницу.',true)}finally{loading=false}}
function scoped(){return data.products.filter(p=>(!$('market').value||p.market===$('market').value)&&(!$('store').value||p.storeId===$('store').value))}
function effective(p){const q=p.pricing;if(!q||q.price===null)return null;return p.market==='WB'?Math.round(q.price*(1-q.discount/100)*100)/100:q.price}
function render(){const scope=scoped(),hidden=scope.filter(PultModel.isInactive).length,visible=scope.filter(p=>!$('hide-inactive').checked||!PultModel.isInactive(p));const waiting=data.batches.filter(b=>b.status==='submitted').length,open=data.batches.filter(b=>['draft','submitted','returned'].includes(b.status)).length;
 $('metrics').innerHTML=[['Товаров в каталоге',nf.format(visible.length),'По выбранным магазинам'],['Заявок на проверке',nf.format(waiting),open+' открытых заявок · все магазины'],['С положительной ценой',nf.format(visible.filter(p=>p.pricing?.price>0).length),'Остальные: цена 0, не загружена или разные размеры']].map(([title,value,note])=>`<article class="metric"><div class="metric-label">${title}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></article>`).join('');
 $('queue-badge').textContent=open;$('hidden-count').textContent=($('hide-inactive').checked?'Скрыто: ':'Непродающихся в списке: ')+hidden;
 const running=Object.values(data.priceJobs).some(j=>j.status==='running');$('refresh-prices').disabled=running||!scope.length;$('refresh-prices').textContent=running?'↻ Загружаем цены…':'↻ Обновить цены';
 const times=visible.map(p=>Date.parse(p.pricing?.importedAt)).filter(Number.isFinite),ids=new Set(scope.map(p=>p.storeId));const errors=Object.entries(data.priceJobs).filter(([id,j])=>ids.has(id)&&j.status==='error').map(([,j])=>j.error);
 $('price-status').textContent=errors.length?errors.join('; '):running?'Загрузка цен идёт в фоне. Полный финансовый импорт не запускается.':times.length?'Цены получены: '+when(Math.min(...times))+' · самый ранний снимок':'Нажмите «Обновить цены», чтобы загрузить значения';
 renderTable();renderQueue();renderJournal();
}
function renderTable(){const q=$('search').value.trim().toLocaleLowerCase('ru-RU'),issue=$('issue').value;
 filtered=scoped().filter(p=>(!$('hide-inactive').checked||!PultModel.isInactive(p))&&(!q||[p.name,p.offer_id,p.sku,p.storeName,p.note.text].join(' ').toLocaleLowerCase('ru-RU').includes(q))&&(!issue||(issue==='attention'&&p.note.flag==='attention')||(issue==='purchase'&&p.note.flag==='purchase')||(issue==='missing'&&!(p.pricing?.price>0))||(issue==='belowcost'&&p.cost?.status==='filled'&&p.cost.currency===p.pricing?.currency&&effective(p)!==null&&effective(p)<p.cost.unitCost))).sort((a,b)=>(a.name||'').localeCompare(b.name||'','ru',{numeric:true}));
 page=Math.max(1,Math.min(page,Math.ceil(filtered.length/pageSize)||1));const view=filtered.slice((page-1)*pageSize,page*pageSize);
 $('product-rows').innerHTML=view.map(p=>`<tr><td><input type="checkbox" data-select="${esc(p.key)}" ${selected.has(p.key)?'checked':''} aria-label="Выбрать ${esc(p.offer_id||p.name)}"></td><td><div class="product-name" title="${esc(p.name)}">${esc(p.name||'Без названия')}</div><span class="sub">${esc(p.offer_id)} · SKU ${esc(p.sku||p.product_id)}</span>${p.note.flag!=='normal'?`<span class="flag ${p.note.flag==='purchase'?'purchase':''}">${p.note.flag==='purchase'?'К закупке':'Проверить'}</span>`:''}${p.note.text?`<span class="note-preview" title="${esc(p.note.text)}">${esc(p.note.text)}</span>`:''}${PultModel.isInactive(p)?'<span class="sub">Архив / снят с продажи</span>':''}</td><td><span class="platform ${p.market==='WB'?'wb':''}">${p.market}</span><span class="sub">${esc(p.storeName.replace('WB · ',''))}</span></td><td class="numeric"><span class="manage-price">${money(p.pricing?.price)}</span>${p.market==='WB'&&p.pricing?.price>0?`<span class="discount-note">−${esc(p.pricing.discount)}% → ${money(effective(p))}</span>`:p.pricing?.multiplePrices?'<span class="sub">Разные цены размеров</span>':''}</td><td class="numeric">${p.cost?.status==='filled'?money(p.cost.unitCost):'<span class="pill muted">Не заполнена</span>'}</td><td class="numeric">${p.quantity===null?'—':nf.format(p.quantity)}</td><td><div class="row-actions"><button class="button secondary" data-edit="${esc(p.key)}" ${PultModel.isInactive(p)?'disabled':''}>Цена</button><button class="button secondary" data-note="${esc(p.key)}">Заметка</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Нет товаров по выбранным условиям.</td></tr>';
 $('table-count').textContent=filtered.length?`${(page-1)*pageSize+1}–${Math.min(page*pageSize,filtered.length)} из ${nf.format(filtered.length)} товаров`:'Найдено 0 товаров';$('page-info').textContent=page+' / '+(Math.ceil(filtered.length/pageSize)||1);$('prev').disabled=page===1;$('next').disabled=page*pageSize>=filtered.length;$('export').disabled=!filtered.length;$('select-all').disabled=!filtered.length;
 const count=view.filter(p=>selected.has(p.key)).length;$('select-page').checked=!!view.length&&count===view.length;$('select-page').indeterminate=count>0&&count<view.length;selection();
}
function selection(){$('selected-count').textContent=selected.size?'Выбрано товаров: '+nf.format(selected.size):'Выберите товары для массового изменения цен';$('bulk-edit').disabled=!selected.size;$('clear-selection').disabled=!selected.size}
function filterChange(){selected.clear();page=1;render()}
function renderQueue(){const f=$('queue-filter').value,list=data.batches.filter(b=>!f||(f==='open'?b.status!=='cancelled':b.status===f));$('queue-list').innerHTML=list.map(b=>`<article class="queue-card"><div><div class="queue-meta">ЗАЯВКА № ${b.number} · ${when(b.createdAt)}</div><h3>${esc(b.title)}</h3><p>${esc(b.reason)}</p><small>${b.rows.length} товаров · ${[...new Set(b.rows.map(r=>r.storeName))].map(esc).join(', ')}</small></div><div><span class="pill ${b.status==='submitted'?'':b.status==='returned'?'warn':'muted'}">${labels[b.status]}</span><button class="button secondary" data-batch="${esc(b.id)}">Проверить →</button></div></article>`).join('')||'<div class="blank-state"><h3>Заявок пока нет</h3><p>Выберите товары в каталоге, рассчитайте новые цены и сохраните черновик для проверки.</p><button class="button secondary" data-goto-catalog>Открыть каталог</button></div>'}
function renderJournal(){$('journal-list').innerHTML=data.events.slice(0,300).map(e=>`<div class="journal-event"><div><strong>${esc(eventLabels[e.type]||e.type)}</strong> · ${esc(e.label)}${e.count?' · '+e.count+' товаров':''}<small>${e.comment?esc(e.comment)+' · ':''}Локальное рабочее место${e.key?' · '+esc(e.key):''}</small></div><time>${when(e.at)}</time></div>`).join('')||'<div class="empty">Действия появятся после сохранения первой заявки или заметки.</div>'}
function invalidate(){previewGeneration++;quote=null;quoteRequest=null;$('preview').innerHTML='';$('save-draft').disabled=true;$('warning-ack').hidden=true;$('accept-warnings').checked=false;$('editor-message').textContent=''}
function openEditor(products){editRows=products;invalidate();requestId=crypto.randomUUID();$('editor-title').textContent=products.length===1?products[0].name:'Массовое изменение цен';$('editor-subtitle').textContent=products.length===1?products[0].storeName+' · '+products[0].offer_id+' · цена '+money(products[0].pricing?.price):'Выбрано '+products.length+' товаров. Перед сохранением проверьте каждое изменение.';$('mode').value=products.length===1?'set':'percent';$('amount').value=products.length===1?(products[0].pricing?.price??''):'';$('rounding').value=products.some(p=>p.market==='WB')?'1':'0';$('draft-title').value=products.length===1?'Цена · '+String(products[0].offer_id||products[0].product_id).slice(0,140):'Массовое изменение цен';$('reason').value='';
 const p=products[0];$('extra-fields').innerHTML=products.length===1?(p.market==='WB'?`<label>Скидка продавца WB, %<input id="extra-discount" type="number" min="0" max="99" step="1" value="${esc(p.pricing?.discount??'')}"></label>`:`<label>Минимальная цена Ozon, ₽<input id="extra-minPrice" type="number" min="0" step="0.01" value="${esc(p.pricing?.minPrice??'')}"></label><label>Цена до скидки Ozon, ₽<input id="extra-oldPrice" type="number" min="0" step="0.01" value="${esc(p.pricing?.oldPrice??'')}"></label>`):'';
 for(const input of $('extra-fields').querySelectorAll('input'))input.oninput=invalidate;$('editor').showModal();
}
function inputRequest(){if($('amount').value.trim()==='')throw Error('Введите изменение цены');const request={targets:editRows.map(p=>({key:p.key,version:p.version})),mode:$('mode').value,amount:Number($('amount').value),rounding:Number($('rounding').value)};if(editRows.length===1){request.fields={};for(const field of ['minPrice','oldPrice','discount']){const input=$('extra-'+field);if(input&&input.value.trim()!=='')request.fields[field]=Number(input.value)}}return request}
function rowTable(rows){return `<div class="preview-table"><table><thead><tr><th>Товар</th><th>Было</th><th>Станет</th><th>Изменение</th><th>Проверка</th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="product-name">${esc(r.name)}</div><span class="sub">${esc(r.storeName)} · ${esc(r.offer_id)}</span></td><td>${money(r.before.price)}${r.market==='WB'?`<span class="sub">Скидка ${esc(r.before.discount)}%</span>`:`<span class="sub">Мин. ${money(r.before.minPrice)}<br>До скидки ${money(r.before.oldPrice)}</span>`}</td><td><b>${money(r.after.price)}</b>${r.market==='WB'?`<span class="sub">Скидка ${esc(r.after.discount)}%<br>Со скидкой ${money(r.effective)}</span>`:`<span class="sub">Мин. ${money(r.after.minPrice)}<br>До скидки ${money(r.after.oldPrice)}</span>`}</td><td>${r.changePercent===null?'—':nf.format(r.changePercent)+'%'}<span class="sub">Себест. ${money(r.cost)}</span></td><td>${r.errors.map(e=>`<div class="validation error-text">${esc(e)}</div>`).join('')}${r.warnings.map(w=>`<div class="validation warning-text">${esc(w)}</div>`).join('')}${!r.errors.length&&!r.warnings.length?'<span class="pill">Проверено</span>':''}</td></tr>`).join('')}</tbody></table></div>`}
function editorError(e){$('editor-message').className='inline-error';$('editor-message').textContent=e.message}
function saveEnabled(){$('save-draft').disabled=editorBusy||!quote?.valid||(quote.warningCount>0&&!$('accept-warnings').checked)}
$('preview-button').onclick=async()=>{if(editorBusy)return;invalidate();editorBusy=true;$('preview-button').disabled=true;try{const request=inputRequest(),generation=previewGeneration;const result=await api('/api/manage/preview',request);if(generation!==previewGeneration)return;quote=result;quoteRequest=request;$('preview').innerHTML=`<div class="preview-stats">Товаров: ${result.rows.length} · с ошибками: ${result.errorCount} · с предупреждениями: ${result.warningCount}</div>`+rowTable(result.rows);$('warning-ack').hidden=!result.warningCount;}catch(e){editorError(e)}finally{editorBusy=false;$('preview-button').disabled=false;saveEnabled()}};
$('save-draft').onclick=async()=>{if(editorBusy||!quote?.valid)return;editorBusy=true;saveEnabled();try{await api('/api/manage/drafts',{...quoteRequest,title:$('draft-title').value,reason:$('reason').value,requestId,previewHash:quote.hash,acceptWarnings:$('accept-warnings').checked});$('editor').close();selected.clear();notice('Черновик сохранён. Передайте заявку на проверку после просмотра изменений.');await load();tab('queue');}catch(e){editorError(e)}finally{editorBusy=false;saveEnabled()}};
function openNote(p){noteProduct=p;$('note-title').textContent=p.name;$('note-subtitle').textContent=p.storeName+' · '+p.offer_id;$('note-flag').value=p.note.flag;$('note-text').value=p.note.text;$('note-message').textContent='';$('note-dialog').showModal()}
$('save-note').onclick=async()=>{$('save-note').disabled=true;try{await api('/api/manage/note',{key:noteProduct.key,version:noteProduct.note.version,text:$('note-text').value,flag:$('note-flag').value});$('note-dialog').close();notice('Заметка к товару сохранена.');await load()}catch(e){$('note-message').className='inline-error';$('note-message').textContent=e.message}finally{$('save-note').disabled=false}};
function openBatch(id){const b=data.batches.find(b=>b.id===id);if(!b)return;batchId=id;$('batch-message').textContent='';$('batch-content').innerHTML=`<h2 class="detail-title">№ ${b.number} · ${esc(b.title)}</h2><p>${esc(b.reason)}</p><div class="batch-summary"><span class="pill">${labels[b.status]}</span><span>${b.rows.length} товаров</span><span>Обновлена ${when(b.updatedAt)}</span></div>${b.returnReason?'<p>Причина возврата: '+esc(b.returnReason)+'</p>':''}${rowTable(b.rows)}<div class="batch-actions">${b.status==='draft'?'<button class="button" data-transition="submitted">Передать на проверку</button>':''}${b.status!=='cancelled'?'<button class="button secondary" data-transition="cancelled">Отменить заявку</button>':''}<button class="button secondary" id="export-batch">↓ Скачать заявку CSV</button></div>${b.status==='submitted'?'<div class="return-box"><label>Причина возврата<input id="return-comment" maxlength="1000" placeholder="Что нужно исправить"></label><button class="text-button" data-transition="returned">Вернуть на доработку</button></div>':''}<div class="blocked-send">Подтверждение руководителя и отправка станут доступны после подключения учётных записей и ключей с правом изменения цен.<br><button class="button" disabled>Подтвердить и отправить на площадки</button></div>`;if(!$('batch-dialog').open)$('batch-dialog').showModal();$('export-batch').onclick=()=>download('Пульт-заявка-'+b.number+'.csv',tableCsv([['Магазин','Артикул','Товар','Цена до','Цена после','Минимальная до','Минимальная после','До скидки раньше','До скидки новая','Скидка WB до','Скидка WB после','Причина','Статус'],...b.rows.map(r=>[r.storeName,r.offer_id,r.name,r.before.price,r.after.price,r.before.minPrice,r.after.minPrice,r.before.oldPrice,r.after.oldPrice,r.before.discount,r.after.discount,b.reason,labels[b.status]])]));}
$('batch-content').onclick=async e=>{const button=e.target.closest('[data-transition]');if(!button)return;const b=data.batches.find(b=>b.id===batchId);for(const item of $('batch-content').querySelectorAll('[data-transition]'))item.disabled=true;try{await api('/api/manage/transition',{id:b.id,version:b.version,status:button.dataset.transition,comment:$('return-comment')?.value});await load();openBatch(b.id)}catch(error){$('batch-message').className='inline-error';$('batch-message').textContent=error.message;for(const item of $('batch-content').querySelectorAll('[data-transition]'))item.disabled=false}};
function tableCsv(table){return '\ufeff'+table.map(row=>row.map(v=>{let s=String(v??'');if(/^\s*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(';')).join('\r\n')}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('export').onclick=()=>download('Пульт-управление-товарами.csv',tableCsv([['Магазин','Площадка','Товар','Артикул','SKU','Базовая цена','Скидка продавца WB, %','Цена со скидкой WB','Себестоимость','Остаток','Метка','Заметка','Цены получены'],...filtered.map(p=>[p.storeName,p.market,p.name,p.offer_id,p.sku,p.pricing?.price,p.pricing?.discount,p.market==='WB'?effective(p):'',p.cost?.unitCost,p.quantity,p.note.flag,p.note.text,p.pricing?.importedAt])]));
$('refresh-prices').onclick=async()=>{$('refresh-prices').disabled=true;try{await api('/api/manage/refresh-prices',{ids:[...new Set(scoped().map(p=>p.storeId))]});notice('Загружаю цены выбранных магазинов. Результат появится автоматически.');await load()}catch(e){notice(e.message,true);$('refresh-prices').disabled=false}};
$('product-rows').onclick=e=>{const edit=e.target.closest('[data-edit]'),note=e.target.closest('[data-note]');if(edit)openEditor([data.products.find(p=>p.key===edit.dataset.edit)]);if(note)openNote(data.products.find(p=>p.key===note.dataset.note))};
$('product-rows').onchange=e=>{if(!e.target.dataset.select)return;const key=e.target.dataset.select;e.target.checked?selected.add(key):selected.delete(key);renderTable()};
$('select-page').onchange=()=>{const checked=$('select-page').checked;for(const p of filtered.slice((page-1)*pageSize,page*pageSize))checked?selected.add(p.key):selected.delete(p.key);renderTable()};
$('select-all').onclick=()=>{selected=new Set(filtered.map(p=>p.key));renderTable()};$('clear-selection').onclick=()=>{selected.clear();renderTable()};$('bulk-edit').onclick=()=>openEditor(data.products.filter(p=>selected.has(p.key)));
$('market').onchange=()=>{storeOptions();filterChange()};$('store').onchange=filterChange;$('issue').onchange=filterChange;$('search').oninput=filterChange;
try{$('hide-inactive').checked=localStorage.getItem('pult-hide-inactive')!=='false'}catch{}
$('hide-inactive').onchange=()=>{try{localStorage.setItem('pult-hide-inactive',String($('hide-inactive').checked))}catch{}filterChange()};
$('prev').onclick=()=>{page--;renderTable()};$('next').onclick=()=>{page++;renderTable()};$('queue-filter').onchange=renderQueue;$('refresh-journal').onclick=load;
$('queue-list').onclick=e=>{const b=e.target.closest('[data-batch]');if(b)openBatch(b.dataset.batch);if(e.target.closest('[data-goto-catalog]'))tab('catalog')};
for(const button of document.querySelectorAll('[data-tab]'))button.onclick=()=>tab(button.dataset.tab);
for(const button of document.querySelectorAll('[data-close]'))button.onclick=()=>$(button.dataset.close).close();
for(const id of ['mode','amount','rounding'])$(id).addEventListener('input',invalidate);$('accept-warnings').onchange=saveEnabled;
tab(location.hash.slice(1)||'catalog');void load();setInterval(()=>{if(!document.hidden&&!document.querySelector('dialog[open]'))void load()},6000);
